import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DaGSOal_.js";const m=JSON.parse('{"title":"D","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/d.md","filePath":"glossaire-a-z/d.md"}'),i={name:"glossaire-a-z/d.md"};function s(o,e,d,l,u,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h1><h2 id="d-parameter-fr-parametre-d" tabindex="-1">d parameter (fr : Paramètre d) <a class="header-anchor" href="#d-parameter-fr-parametre-d" aria-label="Permalink to &quot;d parameter (fr : Paramètre d)&quot;">​</a></h2><p>Le paramètre de protocole utilisé pendant l’ère Shelley qui contrôlait la proportion de blocs produits par les nœuds de genèse fédérés par rapport aux pools de staking communautaires.</p><h2 id="dapp-fr-application-decentralisee" tabindex="-1">DApp (fr : Application décentralisée) <a class="header-anchor" href="#dapp-fr-application-decentralisee" aria-label="Permalink to &quot;DApp (fr : Application décentralisée)&quot;">​</a></h2><p>Une application dont la logique principale s’exécute sous forme de code sur la chaîne, plutôt que sur les serveurs d’une seule entreprise, de sorte que ses règles continuent de fonctionner même si un opérateur cesse ses activités.</p><h2 id="datum-fr-donnee-associee-a-un-utxo" tabindex="-1">Datum (fr : Donnée associée à un UTxO) <a class="header-anchor" href="#datum-fr-donnee-associee-a-un-utxo" aria-label="Permalink to &quot;Datum (fr : Donnée associée à un UTxO)&quot;">​</a></h2><p>Une donnée attachée à un UTxO qu’un contrat intelligent peut lire lorsqu’il détermine si cet UTxO peut être dépensé.</p><p>→ <a href="https://docs.cardano.org/about-cardano/learn/transaction-costs-determinism" target="_blank" rel="noreferrer">Transaction costs and determinism — Cardano Docs</a></p><h2 id="delegation-fr-delegation" tabindex="-1">Delegation (fr : Délégation) <a class="header-anchor" href="#delegation-fr-delegation" aria-label="Permalink to &quot;Delegation (fr : Délégation)&quot;">​</a></h2><p>Le processus consistant à attribuer son stake à un pool de staking sans transférer ses ada.</p><p>→ <a href="https://docs.cardano.org/about-cardano/learn/delegation" target="_blank" rel="noreferrer">Delegation — Cardano Docs</a></p><h2 id="determinism-fr-determinisme" tabindex="-1">Determinism (fr : Déterminisme) <a class="header-anchor" href="#determinism-fr-determinisme" aria-label="Permalink to &quot;Determinism (fr : Déterminisme)&quot;">​</a></h2><p>La propriété selon laquelle un calcul produit toujours les mêmes résultats lorsqu’il reçoit les mêmes entrées.</p><p>→ <a href="https://docs.cardano.org/about-cardano/learn/transaction-costs-determinism" target="_blank" rel="noreferrer">Transaction costs and determinism — Cardano Docs</a></p><h2 id="dex-fr-plateforme-d-echange-decentralisee" tabindex="-1">DEX (fr : Plateforme d’échange décentralisée) <a class="header-anchor" href="#dex-fr-plateforme-d-echange-decentralisee" aria-label="Permalink to &quot;DEX (fr : Plateforme d’échange décentralisée)&quot;">​</a></h2><p>Une plateforme d’échange où les échanges sont exécutés par du code sur la chaîne plutôt que par un opérateur central. Les utilisateurs échangent directement depuis leur portefeuille et ne confient pas la garde de leurs fonds à un opérateur central.</p><h2 id="did-fr-identifiant-decentralise" tabindex="-1">DID (fr : Identifiant décentralisé) <a class="header-anchor" href="#did-fr-identifiant-decentralise" aria-label="Permalink to &quot;DID (fr : Identifiant décentralisé)&quot;">​</a></h2><p>Un identifiant que l’on crée et contrôle soi-même, sans registre central ; l’enregistrement permettant de résoudre cet identifiant se trouve sur une blockchain ou un autre système décentralisé plutôt que dans la base de données d’une seule entreprise.</p><h2 id="dijkstra" tabindex="-1">Dijkstra <a class="header-anchor" href="#dijkstra" aria-label="Permalink to &quot;Dijkstra&quot;">​</a></h2><p>La prochaine ère du registre Cardano et le nom d’un hard fork, en hommage à Edsger Dijkstra. Sa première phase, ciblée pour la fin de 2026 selon le glossaire officiel, doit apporter Linear Leios et les transactions imbriquées (<em>nested transactions</em>). Une deuxième phase doit ajouter Peras.</p><h2 id="djed" tabindex="-1">Djed <a class="header-anchor" href="#djed" aria-label="Permalink to &quot;Djed&quot;">​</a></h2><p>Un protocole de stablecoin surcollatéralisé par des cryptomonnaies sur Cardano, dont l’ancrage au dollar américain est maintenu de manière algorithmique à partir d’une réserve en ada, avec SHEN comme jeton de réserve, plutôt qu’au moyen de réserves en monnaie fiduciaire.</p><h2 id="drep-fr-representant-delegue" tabindex="-1">DRep (fr : Représentant délégué) <a class="header-anchor" href="#drep-fr-representant-delegue" aria-label="Permalink to &quot;DRep (fr : Représentant délégué)&quot;">​</a></h2><p>Un représentant auquel les détenteurs d’ada délèguent leur pouvoir de vote sur la chaîne, afin qu’il vote en leur nom sur les actions de gouvernance.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-1694" target="_blank" rel="noreferrer">CIP-1694 — Spécification officielle</a></p><h2 id="drep-activity-period-fr-periode-d-activite-des-dreps" tabindex="-1">DRep Activity Period (fr : Période d’activité des DReps) <a class="header-anchor" href="#drep-activity-period-fr-periode-d-activite-des-dreps" aria-label="Permalink to &quot;DRep Activity Period (fr : Période d’activité des DReps)&quot;">​</a></h2><p>Le paramètre du protocole qui définit le nombre d’époques pendant lesquelles un DRep peut rester sans voter ou mettre à jour son inscription avant d’être considéré comme inactif. Son pouvoir de vote délégué cesse alors d’être comptabilisé jusqu’à ce qu’il redevienne actif.</p><h2 id="dyor-fr-faites-vos-propres-recherches" tabindex="-1">DYOR (fr : Faites vos propres recherches) <a class="header-anchor" href="#dyor-fr-faites-vos-propres-recherches" aria-label="Permalink to &quot;DYOR (fr : Faites vos propres recherches)&quot;">​</a></h2><p>Expression utilisée dans les communautés crypto pour rappeler aux personnes d’examiner elles-mêmes un projet, une équipe ou une affirmation avant d’investir ou d’agir, plutôt que de se fier uniquement aux arguments de quelqu’un d’autre.</p>',29)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
